# %% ../../nbs/01_tiling.ipynb #2a70e10f
class TileProcessorONNX(
    torch.nn.Module # torch.nn.Module is a base class for all neural network modules in PyTorch.
    ):
    """
    ONNX opset 12 compatible PyTorch module for splitting images into overlapping tiles.
    Fixed input size — all positions pre-computed. Returns ONLY tensor (no list).
    The tracer unrolls the fixed-length loop into Slice + Concat ops.

    If ``input_h`` or ``input_w`` is smaller than ``tile_size`` the image is
    padded up to ``tile_size`` so that at least one full tile is always produced.
    """

    def __init__(
        self, 
        tile_size: int = 256,  # Side length of each square tile
        overlap: int = 32, # Pixel overlap between adjacent tiles 
        input_h: int = 1152, # Expected input height in pixels (after padding) 
        input_w: int = 1632, # Expected input width in pixels (after padding)
        debug: bool = False, # Whether to print debug info at init time (e.g. number of tiles, padding applied)
        ):
        super().__init__()
        self.tile_size = tile_size 
        self.overlap = overlap
        self.stride = tile_size - overlap
        self.input_h = input_h
        self.input_w = input_w
        self.debug = debug

        if self.debug:
            print(f"[TileProcessorONNX::__init__] Called with: tile_size={tile_size}, overlap={overlap}, input_h={input_h}, input_w={input_w}")

        self._setup_tile_layout(debug)

    def _compute_effective_size(self, input_h, input_w, tile_size, debug: bool = False):
        effective_h = max(input_h, tile_size)
        effective_w = max(input_w, tile_size)
        if debug:
            print(f"[TileProcessorONNX::_compute_effective_size] effective_h={effective_h}, effective_w={effective_w}")
        return effective_h, effective_w

    def _compute_num_tiles(self, effective_h, effective_w, stride, overlap, debug: bool = False):
        num_tiles_h = max(1, (effective_h - overlap + stride - 1) // stride)
        num_tiles_w = max(1, (effective_w - overlap + stride - 1) // stride)
        if debug:
            print(f"[TileProcessorONNX::_compute_num_tiles] num_tiles_h={num_tiles_h}, num_tiles_w={num_tiles_w}")
        return num_tiles_h, num_tiles_w

    def _compute_positions(self, num_tiles_h, num_tiles_w, stride, debug: bool = False):
        h_starts_list = []
        w_starts_list = []
        positions = []
        for i in range(num_tiles_h):
            for j in range(num_tiles_w):
                start_h = i * stride
                start_w = j * stride
                h_starts_list.append(start_h)
                w_starts_list.append(start_w)
                positions.append((i, j, start_h, start_w))
        if debug:
            print(f"[TileProcessorONNX::_compute_positions] Computed {len(positions)} positions")
        return h_starts_list, w_starts_list, positions

    def _setup_tile_layout(self, debug: bool = False):
        # Step 1: Calculate effective image size
        effective_h, effective_w = self._compute_effective_size(
            self.input_h, 
            self.input_w, 
            self.tile_size, 
            debug)

        # Step 2: Number of tiles
        self.num_tiles_h, self.num_tiles_w = self._compute_num_tiles(
            effective_h, 
            effective_w, 
            self.stride, 
            self.overlap, 
            debug)

        # Step 3: Pre-compute positions
        self.h_starts_list, self.w_starts_list, self.positions = self._compute_positions(
            self.num_tiles_h, 
            self.num_tiles_w, 
            self.stride, 
            debug
        )
        self.num_tiles = len(self.h_starts_list)

        # Step 4: Final padded size (must cover tiled grid)
        self.padded_h = self.num_tiles_h * self.stride + self.overlap
        self.padded_w = self.num_tiles_w * self.stride + self.overlap

        if debug:
            print(f"[TileProcessorONNX::_setup_tile_layout] Raw padded_h={self.padded_h}, padded_w={self.padded_w}")

        # Step 5: Ensure padded size >= tile_size (for input < tile_size)
        self.padded_h = max(self.padded_h, self.tile_size)
        self.padded_w = max(self.padded_w, self.tile_size)

        # Step 6: Padding needed
        self.pad_h = max(0, self.padded_h - self.input_h)
        self.pad_w = max(0, self.padded_w - self.input_w)

        if debug:
            print(f"[TileProcessorONNX::_setup_tile_layout] Final: tile_size={self.tile_size}, overlap={self.overlap}, stride={self.stride}")
            print(f"[TileProcessorONNX::_setup_tile_layout] Input: ({self.input_h}, {self.input_w})  Effective: ({effective_h}, {effective_w})")
            print(f"[TileProcessorONNX::_setup_tile_layout] Grid: {self.num_tiles_h}x{self.num_tiles_w} tiles, Total tiles: {self.num_tiles}")
            print(f"[TileProcessorONNX::_setup_tile_layout] Padding needed: (h={self.pad_h}, w={self.pad_w}), Final padded: ({self.padded_h}, {self.padded_w})")

    def forward(self, x: 'Tensor') -> 'Tensor':
        """
        Split input tensor into overlapping tiles.
        Uses constant slicing (ONNX opset 12 compatible).

        Args:
            x: Input tensor [B, C, H, W] — must be [B, C, input_h, input_w]

        Returns:
            Tensor of shape [N*B, C, tile_size, tile_size] where N is num_tiles.
            Access tile positions via ``self.positions``.
        """
        if self.debug:
            print(f"[TileProcessorONNX::forward] Input x.shape={x.shape}")

        if self.pad_h > 0 or self.pad_w > 0:
            if self.debug:
                print(f"[TileProcessorONNX::forward] Applying padding: (h={self.pad_h}, w={self.pad_w})")
            x = torch.nn.functional.pad(x, (0, self.pad_w, 0, self.pad_h), mode="constant", value=0)
            if self.debug:
                print(f"[TileProcessorONNX::forward] After padding x.shape={x.shape}")

        tiles = []
        for i in range(self.num_tiles):
            h_start = self.h_starts_list[i]
            w_start = self.w_starts_list[i]
            tile = x[:, :, h_start : h_start + self.tile_size, w_start : w_start + self.tile_size]
            if self.debug:
                print(f"[TileProcessorONNX::forward] Extracted tile {i}: h={h_start}, w={w_start}, tile.shape={tile.shape}")
            tiles.append(tile)
        out = torch.cat(tiles, dim=0)
        if self.debug:
            print(f"[TileProcessorONNX::forward] Output tiles shape: {out.shape}")
        return out

# %% ../../nbs/01_tiling.ipynb #98ec6e86
def visualize_tile_grid(
    tiles: Union[torch.Tensor, np.ndarray], # tensor or array of tiles
    positions: List[Tuple], # list of (row, col, start_h, start_w) for each tile
    max_tiles: int = 16, # maximum number of tiles to display
    figsize: Tuple[int, int] = (16, 12), # figure size
    save_path: Optional[Union[str, Path]] = None # path to save the visualization
) -> None:
    """
    Visualize individual tiles in a grid layout.
    
    """
    
    if isinstance(tiles, torch.Tensor):
        tiles = tiles.cpu().numpy()
    
    n_tiles = min(len(tiles), max_tiles)
    n_cols = int(np.ceil(np.sqrt(n_tiles)))
    n_rows = int(np.ceil(n_tiles / n_cols))
    
    fig, axes = plt.subplots(n_rows, n_cols, figsize=figsize)
    if n_rows == 1 and n_cols == 1:
        axes = [axes]
    elif n_rows == 1 or n_cols == 1:
        axes = axes.flatten()
    else:
        axes = axes.flatten()
    
    for i in range(n_tiles):
        # Handle different tile formats
        if len(tiles[i].shape) == 3:
            tile_img = tiles[i][0] if tiles[i].shape[0] == 1 else tiles[i]
        else:
            tile_img = tiles[i]
        
        axes[i].imshow(tile_img, cmap='gray')
        
        # Add detailed title with position info
        if i < len(positions):
            row, col, start_h, start_w = positions[i]
            title = f'Tile {i}\nRow:{row}, Col:{col}\nPos:({start_h},{start_w})'
        else:
            title = f'Tile {i}'
        
        axes[i].set_title(title, fontsize=10)
        axes[i].axis('off')
    
    # Hide empty subplots
    for i in range(n_tiles, len(axes)):
        axes[i].axis('off')
        axes[i].set_visible(False)
    
    plt.suptitle(f'Individual Tiles Grid (Showing {n_tiles}/{len(tiles)} tiles)', 
                 fontsize=16, fontweight='bold')
    plt.tight_layout()
    
    if save_path:
        plt.savefig(save_path, dpi=150, bbox_inches='tight')
        print(f"Saved: {save_path}")
    
    plt.show()

# %% ../../nbs/01_tiling.ipynb #a46bc9fb
def visualize_tile_overlay(
    original_image: np.ndarray, # original image as numpy array
    tiles: Union[torch.Tensor, np.ndarray], # tensor or array of tiles
    positions: List[Tuple], # list of (row, col, start_h, start_w) for each tile
    tile_size: int = 256, # size of each tile
    overlap: int = 32, # overlap between tiles
    figsize: Tuple[int, int] = (20, 15), # figure size for the plot
    save_path: Optional[Union[str, Path]] = None, # path to save the visualization
    show_grid: bool = True, # whether to show grid lines
    alpha: float = 0.3, # transparency for overlay
    colormap: str = 'tab20' # colormap for different tiles
) -> None:
    """
    Visualize how tiles overlay on the original image with comprehensive display.
    
    """
    
    # Convert tensors to numpy if needed
    if isinstance(tiles, torch.Tensor):
        tiles = tiles.cpu().numpy()
    
    # Handle different image formats
    if len(original_image.shape) == 3 and original_image.shape[2] == 3:
        display_image = original_image
    elif len(original_image.shape) == 3 and original_image.shape[2] == 1:
        display_image = original_image.squeeze(-1)
    else:
        display_image = original_image
    
    # Create figure with subplots
    fig = plt.figure(figsize=figsize)
    
    # Main layout: 2x2 grid
    gs = fig.add_gridspec(2, 2, height_ratios=[2, 1], width_ratios=[2, 1])
    
    # 1. Original image with tile boundaries
    ax1 = fig.add_subplot(gs[0, 0])
    ax1.imshow(display_image, cmap='gray' if len(display_image.shape) == 2 else None)
    ax1.set_title(f'Original Image with Tile Boundaries\n({len(positions)} tiles, size={tile_size}, overlap={overlap})', 
                  fontsize=14, fontweight='bold')
    
    # Create colormap for tiles
    colors = plt.colormaps.get_cmap(colormap)(np.linspace(0, 1, len(positions)))
    
    # Draw tile boundaries
    for i, (row, col, start_h, start_w) in enumerate(positions):
        rect = patches.Rectangle(
            (start_w, start_h), tile_size, tile_size,
            linewidth=2, edgecolor=colors[i], facecolor=colors[i], alpha=alpha,
            label=f'Tile {i}'
        )
        ax1.add_patch(rect)
        
        # Add tile number in center
        center_x = start_w + tile_size // 2
        center_y = start_h + tile_size // 2
        ax1.text(center_x, center_y, str(i), 
                ha='center', va='center', fontsize=8, fontweight='bold',
                bbox=dict(boxstyle='round,pad=0.3', facecolor='white', alpha=0.8))
    
    if show_grid:
        ax1.grid(True, alpha=0.3)
    ax1.set_xlabel('Width (pixels)')
    ax1.set_ylabel('Height (pixels)')
    
    # 2. Tile positions heatmap
    ax2 = fig.add_subplot(gs[0, 1])
    tile_count_map = np.zeros_like(display_image[:, :, 0] if len(display_image.shape) == 3 else display_image)
    
    for i, (row, col, start_h, start_w) in enumerate(positions):
        end_h = min(start_h + tile_size, tile_count_map.shape[0])
        end_w = min(start_w + tile_size, tile_count_map.shape[1])
        tile_count_map[start_h:end_h, start_w:end_w] += 1
    
    im2 = ax2.imshow(
        tile_count_map, 
        cmap='hot', 
        interpolation='nearest')
    ax2.set_title('Tile Overlap Heatmap\n(Darker = More Overlap)', fontsize=12, fontweight='bold')
    plt.colorbar(im2, ax=ax2, label='Number of Overlapping Tiles')
    ax2.set_xlabel('Width (pixels)')
    ax2.set_ylabel('Height (pixels)')
    
    # 3. Sample tiles grid
    ax3 = fig.add_subplot(gs[1, :])
    n_sample_tiles = min(8, len(tiles))  # Show up to 8 sample tiles
    sample_indices = np.linspace(0, len(tiles)-1, n_sample_tiles, dtype=int)
    
    for idx, tile_idx in enumerate(sample_indices):
        ax_tile = plt.subplot(2, n_sample_tiles, n_sample_tiles + idx + 1)
        
        # Handle different tile formats
        if len(tiles[tile_idx].shape) == 3:
            tile_img = tiles[tile_idx][0] if tiles[tile_idx].shape[0] == 1 else tiles[tile_idx]
        else:
            tile_img = tiles[tile_idx]
        
        ax_tile.imshow(tile_img, cmap='gray')
        ax_tile.set_title(f'Tile {tile_idx}', fontsize=10)
        ax_tile.axis('off')
        
        # Add position info
        if tile_idx < len(positions):
            row, col, start_h, start_w = positions[tile_idx]
            ax_tile.text(0.5, -0.1, f'Pos: ({start_h},{start_w})', 
                        transform=ax_tile.transAxes, ha='center', fontsize=8)
    
    plt.tight_layout()
    
    if save_path:
        plt.savefig(save_path, dpi=150, bbox_inches='tight')
        print(f'Tile overlay visualization saved to: {save_path}')
    
    plt.show()

# %% ../../nbs/01_tiling.ipynb #7083fdc6
def visualize_tile_positions(
    image_shape: Tuple[int, int], # shape of the original image (H, W)
    positions: List[Tuple], # list of (row, col, start_h, start_w) for each tile
    tile_size: int = 256, # size of each tile
    figsize: Tuple[int, int] = (12, 8), # figure size
    save_path: Optional[Union[str, Path]] = None # path to save the visualization
) -> None:
    """
    Visualize tile positions as a schematic diagram.
    
    """
    
    fig, (ax1, ax2) = plt.subplots(1, 2, figsize=figsize)
    
    # 1. Tile position schematic
    H, W = image_shape
    colors = plt.cm.tab20(np.linspace(0, 1, len(positions)))
    
    ax1.set_xlim(0, W)
    ax1.set_ylim(H, 0)  # Invert y-axis to match image coordinates
    ax1.set_aspect('equal')
    
    for i, (row, col, start_h, start_w) in enumerate(positions):
        rect = patches.Rectangle(
            (start_w, start_h), tile_size, tile_size,
            linewidth=2, edgecolor=colors[i], facecolor=colors[i], alpha=0.3
        )
        ax1.add_patch(rect)
        
        # Add tile number
        center_x = start_w + tile_size // 2
        center_y = start_h + tile_size // 2
        ax1.text(center_x, center_y, str(i), 
                ha='center', va='center', fontsize=10, fontweight='bold')
    
    ax1.set_title(f'Tile Positions Schematic\n{len(positions)} tiles on {H}×{W} image', 
                  fontsize=12, fontweight='bold')
    ax1.set_xlabel('Width (pixels)')
    ax1.set_ylabel('Height (pixels)')
    ax1.grid(True, alpha=0.3)
    
    # 2. Position statistics
    ax2.axis('off')
    
    # Calculate statistics
    total_pixels = H * W
    tile_pixels = tile_size * tile_size
    coverage_pixels = len(positions) * tile_pixels
    overlap_ratio = (coverage_pixels - total_pixels) / total_pixels if coverage_pixels > total_pixels else 0
    
    stats_text = f"""
    Tile Statistics:
    
    Image Size: {H} x {W} = {total_pixels:,} pixels
    Tile Size: {tile_size} x {tile_size} = {tile_pixels:,} pixels
    Number of Tiles: {len(positions)}
    
    Total Tile Pixels: {coverage_pixels:,}
    Overlap Ratio: {overlap_ratio:.2%}
    
    Position Range:
    Min H: {min(pos[2] for pos in positions)}
    Max H: {max(pos[2] for pos in positions)}
    Min W: {min(pos[3] for pos in positions)}
    Max W: {max(pos[3] for pos in positions)}
    
    Grid Layout:
    Rows: {max(pos[0] for pos in positions) + 1}
    Cols: {max(pos[1] for pos in positions) + 1}
    """
    
    ax2.text(0.1, 0.9, stats_text, transform=ax2.transAxes, 
             fontsize=11, verticalalignment='top', fontfamily='monospace',
             bbox=dict(boxstyle='round,pad=0.5', facecolor='lightgray', alpha=0.8))
    
    plt.tight_layout()
    
    if save_path:
        plt.savefig(save_path, dpi=150, bbox_inches='tight')
        print(f"Tile positions visualization saved to: {save_path}")
    
    plt.show()

